const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el sintetizador de memoria contextual de RAX. Tu función es consolidar el estado del acompañamiento de mentoría.\nREGLAS:\n1. Genera un resumen del estado actual sin sobreescribir ni contradecir decisiones previamente confirmadas.\n2. Identifica objetivos vigentes, decisiones clave, compromisos pendientes y bloqueos detectados.\n3. Si hay contradicciones en la información, inclúyelas en el campo 'uncertainties'.\n4. Salida en formato JSON estricto con los campos: summary (string), confirmedDecisions (array), pendingCommitments (array), blockers (array), uncertainties (array).`;

const userPrompt = JSON.stringify({
  projectName: payload.projectName,
  currentSummary: payload.currentSummary || '',
  recentActivity: payload.recentActivity || [],
  confirmedItems: payload.confirmedItems || [],
  existingGoals: payload.existingGoals || []
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'http://localhost:3000') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Prepare Memory Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {
    summary: 'Error al decodificar la consolidación de memoria',
    uncertainties: ['Salida JSON no válida']
  };
}

const callbackPayload = {
  operationId: 'op_mem_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-03',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: parsed.summary,
    proposals: (parsed.pendingCommitments || []).map(c => ({
      type: 'task',
      title: c.title || c,
      description: c.description || '',
      needsHumanApproval: true,
      uncertainties: []
    })),
    uncertainties: parsed.uncertainties || []
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
